psql -h /var/lib/postgresql/sockets -U consul -d consul_development -c "
DO \$\$
DECLARE
  r RECORD;
  vals TEXT;
BEGIN
  FOR r IN
    SELECT table_name, column_name
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND (column_name LIKE '%\_type' ESCAPE '\' OR column_name = 'kind' OR column_name = 'name' OR column_name = 'key')
      AND table_name NOT IN ('users', 'geozones', 'budget_headings', 'budget_groups', 'budgets', 'organizations')
    ORDER BY table_name, column_name
  LOOP
    EXECUTE format('SELECT string_agg(DISTINCT coalesce(%I::text, ''<NULL>''), '', '' ORDER BY coalesce(%I::text, ''<NULL>'')) FROM %I', r.column_name, r.column_name, r.table_name) INTO vals;
    IF vals IS NOT NULL THEN
      RAISE NOTICE '%.%: %', r.table_name, r.column_name, left(vals, 300);
    END IF;
  END LOOP;
END \$\$;
"

psql -h /var/lib/postgresql/sockets -U consul -d consul_development -c "
DO \$\$
DECLARE
  r RECORD;
  cnt BIGINT;
BEGIN
  FOR r IN SELECT table_name FROM information_schema.tables WHERE table_schema = 'public' ORDER BY table_name LOOP
    EXECUTE format('SELECT count(*) FROM %I', r.table_name) INTO cnt;
    IF cnt > 0 THEN
      RAISE NOTICE '%: %', r.table_name, cnt;
    END IF;
  END LOOP;
END \$\$;
" && psql -h /var/lib/postgresql/sockets -U consul -d consul_development -c "
DO \$\$
DECLARE
  r RECORD;
  vals TEXT;
BEGIN
  FOR r IN
    SELECT table_name, column_name
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND right(column_name, 5) = '_type'
    ORDER BY table_name, column_name
  LOOP
    EXECUTE format('SELECT string_agg(DISTINCT coalesce(%I::text, ''<NULL>''), '', '') FROM %I', r.column_name, r.table_name) INTO vals;
    IF vals IS NOT NULL THEN
      RAISE NOTICE '%.%: %', r.table_name, r.column_name, vals;
    END IF;
  END LOOP;
END \$\$;
"

